'use client';

import { useEffect, useMemo, useRef, useState } from 'react';

const roles = { reviewer: 'Case reviewer', operator: 'Case operator', supervisor: 'Supervisor', administrator: 'Administrator' };
const navItems = [['overview', '⌘', 'Investigation desk'], ['cases', '▣', 'Cases'], ['review', '◉', 'Review queue'], ['cameras', '◫', 'Partner cameras'], ['models', '✦', 'Model governance'], ['policy', '◇', 'Policy controls']];
let googleMapsPromise;

function formatTime(value) {
  return new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kathmandu' }).format(new Date(value));
}

function formatDateInput(value) { return new Date(value).toISOString().slice(0, 16); }

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error('The selected image could not be read.'));
    reader.readAsDataURL(file);
  });
}

async function loadGoogleMaps(key) {
  if (window.google?.maps) return window.google.maps;
  if (!googleMapsPromise) googleMapsPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly`;
    script.async = true;
    script.onload = () => resolve(window.google.maps);
    script.onerror = reject;
    document.head.append(script);
  });
  return googleMapsPromise;
}

function MapContext({ sightings, maps }) {
  const mapRef = useRef(null);
  const [googleReady, setGoogleReady] = useState(false);

  useEffect(() => {
    if (!maps?.enabled || !sightings.length || !mapRef.current) return;
    let cancelled = false;
    loadGoogleMaps(maps.browserKey).then((api) => {
      if (cancelled || !mapRef.current) return;
      const center = sightings.reduce((total, item) => ({ lat: total.lat + item.location.lat / sightings.length, lng: total.lng + item.location.lng / sightings.length }), { lat: 0, lng: 0 });
      const map = new api.Map(mapRef.current, { center, zoom: 14, disableDefaultUI: true, zoomControl: true, gestureHandling: 'cooperative', styles: [{ featureType: 'poi', stylers: [{ visibility: 'off' }] }] });
      sightings.forEach((item) => new api.Marker({ map, position: item.location, title: `${item.source} · ${item.status} · ${Math.round(item.confidence * 100)}%`, icon: { path: api.SymbolPath.CIRCLE, scale: 8, fillColor: item.status === 'verified' ? '#168f8a' : '#d99a21', fillOpacity: 1, strokeColor: '#ffffff', strokeWeight: 2 } }));
      setGoogleReady(true);
    }).catch(() => setGoogleReady(false));
    return () => { cancelled = true; };
  }, [maps, sightings]);

  const fallbackPoints = sightings.map((item, index) => ({ ...item, left: index === 0 ? '28%' : '70%', top: index === 0 ? '63%' : '35%' }));
  return <div className="cw-map relative h-[318px] overflow-hidden bg-[#0d1723]" ref={mapRef}>
    {!googleReady && <>
      <div className="absolute inset-0 opacity-70 [background-image:linear-gradient(23deg,transparent_41%,rgba(81,105,125,.3)_42%,rgba(81,105,125,.3)_43%,transparent_44%),linear-gradient(112deg,transparent_45%,rgba(88,105,123,.24)_46%,rgba(88,105,123,.24)_47%,transparent_48%),linear-gradient(0deg,rgba(37,59,75,.3)_1px,transparent_1px),linear-gradient(90deg,rgba(37,59,75,.3)_1px,transparent_1px)] [background-size:100%_100%,100%_100%,34px_34px,34px_34px]" />
      <div className="absolute left-[-3%] top-[44%] h-px w-[106%] -rotate-[17deg] bg-[#365c72] shadow-[0_-63px_0_-0.3px_rgba(55,91,111,.45),0_81px_0_-0.3px_rgba(55,91,111,.3)]" />
      {fallbackPoints.map((item) => <div key={item.id} className="absolute z-10" style={{ left: item.left, top: item.top }}>
        <div className={`h-4 w-4 rounded-full border-[3px] ${item.status === 'verified' ? 'border-[#d2fffa] bg-mint shadow-[0_0_0_7px_rgba(88,208,204,.13)]' : 'border-[#fff5d7] bg-amber-400 shadow-[0_0_0_7px_rgba(240,181,75,.14)]'}`} />
        <div className="absolute left-5 top-[-6px] min-w-36 rounded border border-[#2d4050] bg-[#101927] px-2 py-1 text-[9px] text-slate-300 shadow-xl"><p>{item.source}</p><b className={item.status === 'verified' ? 'text-mint' : 'text-amber-300'}>{item.status === 'verified' ? 'VERIFIED' : 'UNDER REVIEW'} · {Math.round(item.confidence * 100)}%</b></div>
      </div>)}
    </>}
  </div>;
}

function Button({ children, kind = 'secondary', className = '', ...props }) {
  const styles = kind === 'primary' ? 'cw-button--primary border-[#a9f275] bg-[#a9f275] text-[#071019] hover:bg-[#bafa8d]' : 'cw-button--secondary border-[#303b4c] bg-[#151d2a] text-slate-200 hover:bg-[#202b3c]';
  return <button className={`cw-button rounded-full border px-3.5 py-2.5 text-[11px] font-semibold transition disabled:cursor-not-allowed disabled:opacity-45 ${styles} ${className}`} {...props}>{children}</button>;
}

function Panel({ children, className = '' }) { return <section className={`cw-panel overflow-hidden rounded-[18px] border border-[#202a39] bg-panel shadow-[0_18px_40px_rgba(0,0,0,.22)] ${className}`}>{children}</section>; }

function Metric({ label, value, detail }) { return <article className="cw-metric rounded-[18px] border border-[#202a39] bg-panel px-[18px] py-4 shadow-[0_18px_40px_rgba(0,0,0,.22)]"><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">{label}</p><strong className="my-1 block text-[27px] font-medium tracking-[-.055em]">{String(value).padStart(2, '0')}</strong><p className="text-[10px] text-slate-400">{detail}</p></article>; }

function Modal({ title, kicker, children, onClose }) { return <div className="cw-modal fixed inset-0 z-30 grid place-items-center bg-[#03070cb3] p-6 backdrop-blur-sm"><div className="cw-modal__content w-full max-w-[520px] rounded-[22px] border border-[#364253] bg-[#111824] p-[22px] shadow-2xl"><header className="mb-4 flex items-start justify-between"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">{kicker}</p><h2 className="mt-1 text-lg font-semibold">{title}</h2></div><button onClick={onClose} className="cw-icon-button text-2xl leading-none text-slate-400 hover:text-white" aria-label="Close">×</button></header>{children}</div></div>; }

function Input({ label, ...props }) { return <label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">{label}<input className="cw-input mt-1.5 w-full rounded-[11px] border border-[#354155] bg-[#0b111a] px-3 py-3 text-xs text-slate-100 outline-none focus:border-mint" {...props} /></label>; }

function PlaceDropzone({ file, onFile, onError, maxBytes, disabled = false }) {
  const inputRef = useRef(null);
  const [dragging, setDragging] = useState(false);
  const acceptFile = (candidate) => {
    if (!candidate) return;
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(candidate.type)) return onError?.('Choose a JPEG, PNG, or WebP image.');
    if (candidate.size > maxBytes) return onError?.(`Choose an image smaller than ${Math.round(maxBytes / (1024 * 1024))} MB.`);
    onError?.(''); onFile(candidate);
  };
  const handleDrop = (event) => {
    event.preventDefault(); setDragging(false);
    if (disabled) return;
    const candidate = event.dataTransfer.files?.[0];
    if (candidate) return acceptFile(candidate);
    if (event.dataTransfer.types?.includes('text/uri-list')) return onError?.('Website image drags provide a link, not a file. Save an authorized image locally, then drop it here.');
    onError?.('Drop a local image file or choose one from your device.');
  };
  return <div onDragEnter={(event) => { event.preventDefault(); if (!disabled) setDragging(true); }} onDragOver={(event) => event.preventDefault()} onDragLeave={(event) => { event.preventDefault(); setDragging(false); }} onDrop={handleDrop} className={`mt-3 rounded-lg border border-dashed p-5 text-center transition ${disabled ? 'cursor-wait opacity-65' : dragging ? 'border-mint bg-[#16313a]' : 'border-[#405066] bg-[#0b111a] hover:border-[#70bcb7]'}`}>
    <input ref={inputRef} type="file" accept="image/jpeg,image/png,image/webp" disabled={disabled} className="sr-only" onChange={(event) => acceptFile(event.target.files?.[0])} />
    <span className="mx-auto grid h-10 w-10 place-items-center rounded-full border border-[#3b566a] bg-[#122332] text-lg text-[#80cfc8]">⌖</span>
    <p className="mt-3 text-[12px] font-semibold text-slate-200">{disabled ? 'Reading local evidence…' : 'Drop an authorized image here'}</p>
    <p className="mt-1 text-[10px] leading-relaxed text-slate-400">JPEG, PNG, or WebP · up to {Math.round(maxBytes / (1024 * 1024))} MB · local file required</p>
    <button type="button" disabled={disabled} onClick={() => inputRef.current?.click()} className="mt-3 text-[11px] font-semibold text-[#80cfc8] underline decoration-[#476271] underline-offset-4 disabled:cursor-not-allowed">Choose image</button>
    {file && <div className="mt-4 flex items-center gap-3 rounded border border-[#315467] bg-[#101f2c] px-3 py-2 text-left"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#19443f] text-[11px] text-emerald-200">✓</span><div className="min-w-0 flex-1"><p className="truncate text-[11px] font-semibold text-slate-100">{file.name}</p><p className="mt-0.5 text-[9px] text-slate-400">{(file.size / 1024 / 1024).toFixed(2)} MB · ready to analyse</p></div><button type="button" disabled={disabled} onClick={() => { onFile(null); onError?.(''); }} className="text-[10px] font-semibold text-slate-400 hover:text-white">Remove</button></div>}
  </div>;
}

function PlaceAnalysisSummary({ detection, outcome, canAnalyse, demoMode, onAnalyse, onSynthetic }) {
  const geocoderReady = Boolean(detection?.pilotGazetteerEnabled || detection?.localGeocoderEnabled || detection?.googleVisionFallbackEnabled);
  const steps = [
    ['01', 'Metadata', 'Embedded GPS is read locally.', Boolean(detection?.metadataEnabled)],
    ['02', 'Sign text', 'Local OCR checks visible place names.', Boolean(detection?.localOcrEnabled)],
    ['03', 'Address match', geocoderReady ? 'A configured gazetteer can resolve a candidate.' : 'No approved address gazetteer is available yet.', geocoderReady],
  ];
  const noSignal = outcome?.disposition === 'no_location_signal';
  const failed = outcome?.disposition === 'error';
  const queued = outcome?.disposition === 'pending_human_review';
  return <Panel className="mt-3.5"><header className="flex flex-wrap items-start justify-between gap-4 border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">IMAGE LOCATION WORKFLOW</p><h2 className="mt-1 text-base font-semibold">See what the image check can do</h2></div><span className={`rounded-full border px-2.5 py-1 text-[9px] font-semibold ${geocoderReady ? 'border-[#2d514b] bg-[#173b34] text-emerald-200' : 'border-[#674c27] bg-[#372a17] text-amber-200'}`}>{geocoderReady ? 'ADDRESS LOOKUP READY' : 'OCR + GPS READY'}</span></header><div className="grid gap-4 p-5 lg:grid-cols-[1.15fr_.85fr]"><div className="grid gap-2 sm:grid-cols-3">{steps.map(([number, title, copy, ready]) => <article key={title} className={`rounded-md border p-3 ${ready ? 'border-[#2d514b] bg-[#10231f]' : 'border-[#4f4025] bg-[#211b14]'}`}><span className={`text-[9px] font-bold tracking-[.12em] ${ready ? 'text-[#80cfc8]' : 'text-amber-200'}`}>{number} · {ready ? 'READY' : 'LIMITED'}</span><h3 className="mt-4 text-[12px] font-semibold">{title}</h3><p className="mt-1 text-[10px] leading-relaxed text-slate-400">{copy}</p></article>)}</div><div className={`rounded-md border p-4 ${queued ? 'border-[#2d514b] bg-[#10231f]' : failed ? 'border-[#59303b] bg-[#261821]' : noSignal ? 'border-[#674c27] bg-[#211b14]' : 'border-[#2d4050] bg-[#0e1622]'}`}><div className="flex items-center justify-between gap-3"><p className="text-[9px] font-bold tracking-[.12em] text-slate-400">{outcome ? 'LATEST ANALYSIS' : 'START HERE'}</p>{outcome && <span className={`rounded-full px-2 py-1 text-[8px] font-bold ${queued ? 'bg-[#173b34] text-emerald-200' : failed ? 'bg-[#442730] text-rose-200' : 'bg-[#49361b] text-amber-200'}`}>{queued ? 'QUEUED FOR REVIEW' : failed ? 'NEEDS ATTENTION' : 'NO LEAD CREATED'}</span>}</div>{outcome ? <><h3 className="mt-3 text-[13px] font-semibold">{queued ? outcome.placeLead?.label || 'Possible place lead sent to review' : failed ? 'The image could not be analysed' : 'No reliable location was found'}</h3><p className="mt-2 text-[10px] leading-relaxed text-slate-300">{outcome.explanation}</p><p className="mt-3 text-[9px] text-slate-500">{outcome.filename ? `Source: ${outcome.filename}` : 'No raw image is retained in the console.'}</p></> : <><h3 className="mt-3 text-[13px] font-semibold">Analyse a local, authorized image</h3><p className="mt-2 text-[10px] leading-relaxed text-slate-400">You will always see whether metadata, sign text, or an address candidate was found. A no-result remains an audited outcome, not a silent failure.</p></>}<div className="mt-4 flex flex-wrap gap-2">{canAnalyse && <Button kind="primary" className="px-3 py-2" onClick={onAnalyse}>{outcome ? 'Try another image' : 'Analyse image'}</Button>}{demoMode && canAnalyse && <Button className="px-3 py-2" onClick={onSynthetic}>Use synthetic sample</Button>}</div></div></div></Panel>;
}

function PlaceAnalysisFeedback({ outcome, fileError, geocoderReady }) {
  if (!outcome && !fileError) return null;
  const error = outcome?.disposition === 'error';
  const noSignal = outcome?.disposition === 'no_location_signal';
  const copy = fileError || outcome?.explanation;
  return <div className={`mt-3 rounded border px-3 py-2.5 text-[10px] leading-relaxed ${error || fileError ? 'border-[#59303b] bg-[#261821] text-rose-100' : noSignal ? 'border-[#674c27] bg-[#211b14] text-amber-100' : 'border-[#2d514b] bg-[#10231f] text-emerald-100'}`}><div className="flex items-center justify-between gap-3"><b className="text-[9px] tracking-[.1em]">{error || fileError ? 'CHECK THE IMAGE' : noSignal ? 'ANALYSIS COMPLETE — NO LEAD' : 'ANALYSIS COMPLETE'}</b>{outcome?.filename && <span className="max-w-[180px] truncate text-[9px] opacity-70">{outcome.filename}</span>}</div><p className="mt-1.5">{copy}</p>{noSignal && !geocoderReady && <p className="mt-2 border-t border-amber-900/70 pt-2 text-amber-200">Sign text can be checked locally, but turning it into an address requires an approved internal gazetteer. Try an image with embedded GPS or ask an administrator to configure one.</p>}</div>;
}

function PremiumOverview({ currentCase, data, pending, verified, pendingPlaceLeads, placeLeads, target, role, cameraById, onView, onOpenModal, onReset }) {
  const canOperate = role !== 'reviewer';
  const pendingCount = pending.length + pendingPlaceLeads.length;
  const nextSighting = pending[0];
  const nextPlace = pendingPlaceLeads[0];
  const placeReady = Boolean(data.placeDetection?.pilotGazetteerEnabled || data.placeDetection?.localGeocoderEnabled || data.placeDetection?.googleVisionFallbackEnabled);
  const activeWatchlists = data.watchlists.filter((item) => item.status === 'active').length;
  return <div className="cw-command-space">
    <section className="cw-case-hero">
      <div className="cw-case-hero__copy"><div className="cw-kicker"><span className="cw-live-dot" />Active investigation · {currentCase?.caseNumber}</div><h1>{currentCase?.title || 'Investigation desk'}</h1><p>{currentCase?.accessScope || 'Named partner'} scope · authority remains active until {currentCase ? formatTime(currentCase.expiresAt) : '—'} NPT</p></div>
      <div className="cw-case-hero__actions">{data.demoMode && role === 'administrator' && <Button onClick={onReset}>Restore demo</Button>}<Button onClick={() => onView('review')}>Review queue <span className="ml-1.5 rounded-full bg-white/10 px-1.5 py-0.5 text-[9px]">{String(pendingCount).padStart(2, '0')}</span></Button>{canOperate && <Button kind="primary" onClick={() => onOpenModal('watchlist')}>New watchlist <span className="ml-1.5">↗</span></Button>}</div>
    </section>

    <section className="cw-command-stats" aria-label="Case summary"><div><span>WATCHLISTS</span><b>{String(activeWatchlists).padStart(2, '0')}</b><small>active and time-bound</small></div><div><span>REVIEW QUEUE</span><b>{String(pendingCount).padStart(2, '0')}</b><small>human decisions required</small></div><div><span>VERIFIED</span><b>{String(verified.length).padStart(2, '0')}</b><small>case-ready sightings</small></div><div><span>PARTNER SOURCES</span><b>{String(data.cameras.length).padStart(2, '0')}</b><small>fixed-location coverage</small></div></section>

    <section className="cw-primary-workspace">
      <Panel className="cw-route-panel"><header><div><p>CASE ROUTE</p><h2>Evidence context</h2></div><span className="cw-subtle-status">{verified.length} verified · {pending.length} under review</span></header><div className="cw-route-notice">Observed route context only. It does not indicate a vehicle’s current location.</div><MapContext sightings={data.map.sightings || []} maps={data.maps} /><footer><span>{data.maps?.enabled ? 'Google Maps visualization' : 'Case map context'}</span><button onClick={() => onView('cameras')}>View partner sources →</button></footer></Panel>
      <Panel className="cw-decision-panel"><header><div><p>NEXT DECISION</p><h2>{pendingCount ? 'Review with context' : 'Queue is clear'}</h2></div><span className={pendingCount ? 'cw-count-badge' : 'cw-clear-badge'}>{pendingCount ? `${String(pendingCount).padStart(2, '0')} waiting` : 'All clear'}</span></header>{nextSighting ? <div className="cw-decision-body"><div className="cw-decision-plate">{nextSighting.plateRead || 'NO PLATE READ'}</div><div className="cw-decision-meta"><span><small>CONFIDENCE</small><b>{Math.round(nextSighting.confidence * 100)}%</b></span><span><small>SOURCE</small><b>{cameraById(nextSighting.cameraId)?.name || 'Partner camera'}</b></span><span><small>CAPTURED</small><b>{formatTime(nextSighting.capturedAt)} NPT</b></span></div><p>Compare the plate, vehicle description, source integrity, and route context before a decision is recorded.</p><Button kind="primary" className="w-full" onClick={() => onView('review')}>Open reviewer workspace</Button></div> : nextPlace ? <div className="cw-decision-body"><div className="cw-place-symbol">⌖</div><h3>{nextPlace.label || 'Possible image location'}</h3><p>{nextPlace.explanation}</p><Button kind="primary" className="w-full" onClick={() => onView('review')}>Review place lead</Button></div> : <div className="cw-decision-empty"><span>✓</span><h3>No decision is waiting</h3><p>New partner candidates and image leads will appear here when they are ready for a trained reviewer.</p></div>}</Panel>
    </section>

    <section className="cw-support-workspace">
      <Panel className="cw-target-panel"><header><div><p>ACTIVE TARGET</p><h2>{target ? target.plate : 'No current watchlist'}</h2></div><button onClick={() => onView('cases')}>Manage →</button></header>{target ? <div className="cw-target-grid"><div><small>VEHICLE</small><b>{target.vehicle.make} {target.vehicle.model}</b></div><div><small>DESCRIPTOR</small><b>{target.vehicle.color} · {target.vehicle.type || 'Unspecified'}</b></div><div><small>AUTO-EXPIRES</small><b>{formatTime(target.expiresAt)} NPT</b></div></div> : <p className="cw-panel-empty">Create a time-bound watchlist before an edge match can enter this case.</p>}</Panel>
      <Panel className="cw-place-tool"><header><div><p>IMAGE PLACE LEADS</p><h2>Analyse only when it helps</h2></div><span className={placeReady ? 'cw-ready-label' : 'cw-limited-label'}>{placeReady ? 'LOCAL MATCHING READY' : 'GPS + OCR ONLY'}</span></header><div className="cw-place-tool__body"><div><span className="cw-tool-orb">⌁</span><p>{placeReady ? 'Recognized local landmarks can become reviewer-gated leads.' : 'Embedded GPS and local sign text are checked without external image retrieval.'}</p><small>{placeLeads.length} recorded place lead{placeLeads.length === 1 ? '' : 's'} in this case</small></div>{canOperate && <Button kind="primary" onClick={() => onOpenModal('place')}>Analyse image</Button>}</div></Panel>
    </section>
  </div>;
}

export default function InvestigationConsole({ authenticatedUser, onLogout }) {
  const [role, setRole] = useState(authenticatedUser?.role || 'reviewer');
  const [view, setView] = useState('overview');
  const [data, setData] = useState({ cases: [], watchlists: [], cameras: [], sightings: [], placeLeads: [], datasets: [], models: [], modelFindings: [], map: { sightings: [] }, audit: [], maps: null, placeDetection: null, modelGovernance: null, demoMode: false });
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState('');
  const [modal, setModal] = useState(null);
  const [reasons, setReasons] = useState({});
  const [placeFile, setPlaceFile] = useState(null);
  const [placeFileError, setPlaceFileError] = useState('');
  const [placeSubmitting, setPlaceSubmitting] = useState(false);
  const [placeAnalysis, setPlaceAnalysis] = useState(null);

  const api = async (path, options = {}, actingRole = role) => {
    const response = await fetch(path, { ...options, headers: { 'content-type': 'application/json', 'x-demo-role': actingRole, 'x-demo-user': `demo.${actingRole}`, ...(options.headers || {}) } });
    const type = response.headers.get('content-type') || '';
    const body = type.includes('application/json') ? await response.json() : await response.text();
    if (!response.ok) throw new Error(body?.error?.message || 'The request could not be completed.');
    return body;
  };
  const showNotice = (message) => { setNotice(message); window.setTimeout(() => setNotice(''), 3500); };
  const reload = async (actingRole = role) => {
    try {
      setLoading(true);
      const cases = await api('/api/cases', {}, actingRole);
      const caseId = cases.cases[0]?.id || 'case_KTM_0817';
      const [watchlists, cameras, sightings, placeLeads, datasets, models, modelFindings, map, audit, config] = await Promise.all([api(`/api/watchlists?caseId=${caseId}`, {}, actingRole), api('/api/cameras', {}, actingRole), api(`/api/sightings?caseId=${caseId}`, {}, actingRole), api(`/api/place-leads?caseId=${caseId}`, {}, actingRole), api(`/api/training/datasets?caseId=${caseId}`, {}, actingRole), api(`/api/models?caseId=${caseId}`, {}, actingRole), api(`/api/model-findings?caseId=${caseId}`, {}, actingRole), api(`/api/map-layer?caseId=${caseId}&include=all`, {}, actingRole), api(`/api/audit?caseId=${caseId}`, {}, actingRole), api('/api/config', {}, actingRole)]);
      setData({ cases: cases.cases, watchlists: watchlists.watchlists, cameras: cameras.cameras, sightings: sightings.sightings, placeLeads: placeLeads.placeLeads, datasets: datasets.datasets, models: models.models, modelFindings: modelFindings.findings, map, audit: audit.records, maps: config.maps, placeDetection: config.placeDetection, modelGovernance: config.modelGovernance, demoMode: config.demoMode });
    } catch (error) { showNotice(error.message); } finally { setLoading(false); }
  };
  useEffect(() => { const saved = window.localStorage.getItem('civicwatch-demo-role'); if (saved && roles[saved]) setRole(saved); }, []);
  useEffect(() => { reload(); }, [role]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (modal === 'place') { setPlaceFile(null); setPlaceFileError(''); setPlaceAnalysis(null); return; }
    setPlaceFile(null); setPlaceFileError('');
  }, [modal]);

  const currentCase = data.cases[0];
  const related = data.sightings.filter((item) => item.caseId === currentCase?.id);
  const pending = related.filter((item) => item.status === 'pending_review');
  const verified = related.filter((item) => item.status === 'verified');
  const placeLeads = data.placeLeads.filter((item) => item.caseId === currentCase?.id);
  const pendingPlaceLeads = placeLeads.filter((item) => item.status === 'pending_review');
  const modelFindings = data.modelFindings.filter((item) => item.caseId === currentCase?.id);
  const pendingModelFindings = modelFindings.filter((item) => item.status === 'pending_review');
  const target = data.watchlists.find((item) => item.caseId === currentCase?.id && item.status === 'active');
  const cameraById = (id) => data.cameras.find((item) => item.id === id);
  const watchlistById = (id) => data.watchlists.find((item) => item.id === id);

  const review = async (id, decision) => {
    const reason = reasons[id]?.trim();
    if (!reason) return showNotice('Reviewer reasoning is required before a candidate can be decided.');
    try { await api(`/api/sightings/${id}/review`, { method: 'POST', body: JSON.stringify({ decision, reason }) }); await reload(); showNotice(decision === 'approve' ? 'Sighting verified and added to the case map.' : `Candidate ${decision}d. The audit chain was updated.`); } catch (error) { showNotice(error.message); }
  };
  const reviewPlaceLead = async (id, decision) => {
    const reasonKey = `place:${id}`;
    const reason = reasons[reasonKey]?.trim();
    if (!reason) return showNotice('Reviewer reasoning is required before a place lead can be decided.');
    try { await api(`/api/place-leads/${id}/review`, { method: 'POST', body: JSON.stringify({ decision, reason }) }); await reload(); showNotice(decision === 'approve' ? 'Place lead verified for case use.' : `Place lead ${decision === 'reject' ? 'rejected' : 'escalated'}. The audit chain was updated.`); } catch (error) { showNotice(error.message); }
  };
  const reviewModelFinding = async (id, decision) => {
    const reasonKey = `model:${id}`;
    const reason = reasons[reasonKey]?.trim();
    if (!reason) return showNotice('Reviewer reasoning is required before a model finding can be decided.');
    try { await api(`/api/model-findings/${id}/review`, { method: 'POST', body: JSON.stringify({ decision, reason }) }); await reload(); showNotice(decision === 'approve' ? 'Model finding accepted as case evidence; it did not verify a location automatically.' : `Model finding ${decision === 'reject' ? 'rejected' : 'escalated'}. The audit chain was updated.`); } catch (error) { showNotice(error.message); }
  };
  const createSyntheticPlaceLead = async () => {
    try { const response = await api('/api/place-leads', { method: 'POST', body: JSON.stringify({ caseId: currentCase.id, demo: true }) }); setPlaceAnalysis({ ...response, filename: 'Synthetic Kathmandu sample' }); setModal(null); await reload(); showNotice(response.disposition === 'pending_human_review' ? 'Synthetic place lead added to the reviewer queue.' : response.explanation); } catch (error) { setPlaceAnalysis({ disposition: 'error', explanation: error.message, filename: 'Synthetic Kathmandu sample' }); showNotice(error.message); }
  };
  const exportVertexManifest = async (dataset) => {
    try {
      const response = await fetch(`/api/training/datasets/${dataset.id}/vertex-manifest?download=1`, { headers: { 'x-demo-role': role, 'x-demo-user': `demo.${role}` } });
      if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.error?.message || 'The Vertex handoff could not be exported.'); }
      const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `vertex-handoff-${dataset.id}.ndjson`; link.click(); URL.revokeObjectURL(url); showNotice('Reviewer-verified labels exported as a controlled Vertex handoff.');
    } catch (error) { showNotice(error.message); }
  };
  const submitModal = async (event) => {
    event.preventDefault();
    const values = Object.fromEntries(new FormData(event.currentTarget));
    try {
      if (modal === 'place') {
        const image = placeFile || values.image;
        const maxBytes = data.placeDetection?.maxImageBytes || 5 * 1024 * 1024;
        if (!(image instanceof File) || !image.size) throw new Error('Select an authorized image to analyze.');
        if (image.size > maxBytes) throw new Error('The selected image must be 5 MB or smaller.');
        setPlaceSubmitting(true);
        try {
          const response = await api('/api/place-leads', { method: 'POST', body: JSON.stringify({ caseId: currentCase.id, imageBase64: await fileToDataUrl(image), mimeType: image.type, filename: image.name, submitterAuthority: values.submitterAuthority }) });
          setPlaceAnalysis({ ...response, filename: image.name }); await reload();
          if (response.disposition === 'pending_human_review') { setModal(null); showNotice(response.placeLead?.address ? `Possible address lead added: ${response.placeLead.address}` : 'Possible place lead added to the reviewer queue.'); }
          else { setPlaceFile(null); showNotice(response.explanation); }
        } finally { setPlaceSubmitting(false); }
        return;
      }
      if (modal === 'watchlist') await api('/api/watchlists', { method: 'POST', body: JSON.stringify({ caseId: currentCase.id, plate: values.plate, expiresAt: new Date(values.expiresAt).toISOString(), vehicle: { make: values.make, model: values.model, color: values.color } }) });
      if (modal === 'case') await api('/api/cases', { method: 'POST', body: JSON.stringify(values) });
      if (modal === 'search') await api('/api/search-jobs', { method: 'POST', body: JSON.stringify({ caseId: currentCase.id, reference: { evidenceId: values.evidenceId, checksum: values.checksum } }) });
      if (modal === 'camera') await api('/api/cameras', { method: 'POST', body: JSON.stringify({ name: values.name, owner: values.owner, direction: values.direction, retentionDays: Number(values.retentionDays), authorizationRef: values.authorizationRef, location: { lat: Number(values.lat), lng: Number(values.lng), label: 'Pending partner confirmation' } }) });
      if (modal === 'dataset') await api('/api/training/datasets', { method: 'POST', body: JSON.stringify({ caseId: currentCase.id, name: values.name, task: values.task, description: values.description, authorizationRef: values.authorizationRef, storageRegion: values.storageRegion, labelSchema: JSON.parse(values.labelSchema || '{}') }) });
      if (modal === 'training-example') await api(`/api/training/datasets/${values.datasetId}/examples`, { method: 'POST', body: JSON.stringify({ sourceHash: values.sourceHash, storageReference: values.storageReference, checksum: values.checksum, sourceFilename: values.sourceFilename, mimeType: values.mimeType, submitterAuthority: values.submitterAuthority, annotation: JSON.parse(values.annotation) }) });
      if (modal === 'model') await api('/api/models', { method: 'POST', body: JSON.stringify({ datasetId: values.datasetId, name: values.name, provider: values.provider, task: values.task, version: values.version, status: values.status, metrics: JSON.parse(values.metrics || '{}'), approvalRef: values.approvalRef }) });
      setModal(null); await reload(); showNotice(modal === 'search' ? 'Restricted reference-media search queued.' : modal === 'training-example' ? 'Training label submitted to the reviewer queue.' : modal === 'dataset' ? 'Case-scoped training dataset created and audited.' : modal === 'model' ? 'Model profile registered; it cannot make autonomous decisions.' : 'Protected record created and audited.');
    } catch (error) { if (modal === 'place') setPlaceAnalysis({ disposition: 'error', explanation: error.message, filename: placeFile?.name || null }); showNotice(error.message); }
  };
  const exportAudit = async () => { try { const response = await fetch(`/api/audit/export?caseId=${currentCase.id}`, { headers: { 'x-demo-role': role, 'x-demo-user': `demo.${role}` } }); if (!response.ok) throw new Error('Audit export is limited to supervisors and administrators.'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `audit-${currentCase.caseNumber}.ndjson`; link.click(); URL.revokeObjectURL(url); showNotice('Case audit export downloaded.'); } catch (error) { showNotice(error.message); } };
  const resetDemo = async () => { try { await api('/api/demo/reset', { method: 'POST', body: JSON.stringify({}) }); setReasons({}); await reload(); showNotice('Synthetic demo scenario restored.'); } catch (error) { showNotice(error.message); } };

  const pageTitle = view === 'overview' ? currentCase?.title || 'Investigation desk' : ({ cases: 'Active authorizations', review: 'Candidate assessment', cameras: 'Partner camera registry', models: 'Model governance', policy: 'Boundaries are enforced by design.' }[view]);
  if (loading && !currentCase) return <main className="grid min-h-screen place-items-center bg-canvas text-sm text-slate-400">Loading controlled investigation workspace…</main>;

  return <div className="cw-console flex min-h-screen bg-canvas">
    <aside className="cw-sidebar fixed inset-y-0 left-0 z-10 flex w-[250px] flex-col border-r border-[#202938] bg-[#0d121d] px-3.5 pb-4 pt-7">
      <a href="#overview" onClick={() => setView('overview')} className="mb-10 ml-3.5 flex items-center gap-3 text-xs tracking-[.09em]"><span className="grid h-[31px] w-[31px] rotate-45 place-content-center gap-0.5 border-[1.5px] border-signal p-1.5"><i className="block h-0.5 w-3 bg-signal" /><i className="block h-0.5 w-1.5 bg-signal" /><i className="block h-0.5 w-3 bg-signal" /></span><span><b className="block">CIVICWATCH</b><small className="text-[9px] text-slate-500">NEPAL · PILOT</small></span></a>
      <nav className="grid gap-1">{navItems.map(([id, icon, label]) => <button key={id} onClick={() => setView(id)} className={`flex items-center gap-3 rounded-md px-3.5 py-2.5 text-left text-[13px] transition ${view === id ? 'bg-[#1a2333] text-white shadow-[inset_2px_0_0_#cf4f5e]' : 'text-slate-400 hover:bg-[#141c2a] hover:text-slate-200'}`}><span className="w-4 text-center text-base">{icon}</span>{label}{id === 'cases' && <b className="ml-auto text-[10px]">{String(data.cases.length).padStart(2, '0')}</b>}{id === 'review' && pending.length > 0 && <b className="ml-auto rounded-full bg-[#742e3d] px-1.5 py-0.5 text-[10px] text-rose-100">{String(pending.length).padStart(2, '0')}</b>}</button>)}</nav>
      <div className="mt-auto border-t border-[#232d3e]"><div className="flex items-center gap-2.5 px-3 py-4"><i className="h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_0_4px_rgba(97,201,140,.12)]" /><span><small className="block text-[9px] tracking-[.13em] text-slate-500">EDGE NETWORK</small><b className="text-[11px]">3 / 3 reporting</b></span></div><div className="flex items-center gap-2 border-t border-[#232d3e] px-2.5 pt-4"><span className="grid h-7 w-7 place-items-center rounded-full bg-[#385265] text-[10px] font-bold text-[#c8f1ec]">AS</span><span className="min-w-0 flex-1"><b className="block text-[11px]">Asha Shrestha</b><small className="block text-[9px] text-slate-500">{roles[role]}</small></span><span className="text-slate-500">⌄</span></div></div>
    </aside>

    <main className="cw-main ml-[250px] w-[calc(100%-250px)] flex-1">
      <header className="cw-topbar sticky top-0 z-[5] flex h-[68px] items-center justify-between border-b border-[#1e2938] bg-[#090d16eb] px-12 backdrop-blur"><div><span className="text-[10px] font-bold tracking-[.13em] text-slate-500">ACTIVE CASE</span><b className="ml-2.5 text-[11px]">{currentCase?.caseNumber}</b></div><div className="flex items-center gap-3"><span className="rounded-full border border-[#2d514b] bg-[#2e64571f] px-2.5 py-1.5 text-[11px] text-[#9bd7c2]"><i className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-emerald-400" />{authenticatedUser?.email || 'Case-scoped session'}</span><select disabled={Boolean(authenticatedUser)} value={role} onChange={(event) => { window.localStorage.setItem('civicwatch-demo-role', event.target.value); setRole(event.target.value); }} className="cw-role-select rounded-full border border-[#293545] bg-[#121926] px-3 py-1.5 text-[11px] text-slate-300 outline-none">{Object.entries(roles).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select>{onLogout && <button onClick={onLogout} className="cw-signout rounded-full border border-[#493642] px-3 py-1.5 text-[10px] font-semibold text-rose-200 hover:bg-[#281b25]">Sign out</button>}</div></header>

      <div className="cw-content px-12 py-9">
        {view === 'overview' && <PremiumOverview currentCase={currentCase} data={data} pending={pending} verified={verified} pendingPlaceLeads={pendingPlaceLeads} placeLeads={placeLeads} target={target} role={role} cameraById={cameraById} onView={setView} onOpenModal={setModal} onReset={resetDemo} />}

        {view === 'legacy-overview' && <>
          <div className="mb-6 flex items-end justify-between gap-8"><div><p className="text-[10px] font-bold tracking-[.13em] text-slate-400">INVESTIGATION DESK <span className="text-signal">•</span> AUTHORITY VALID UNTIL 21 AUG, 23:59 NPT {data.demoMode && <span className="ml-2 rounded border border-amber-700/70 bg-amber-950/40 px-1.5 py-0.5 text-amber-200">SYNTHETIC DEMO DATA</span>}</p><h1 className="mt-2 text-[29px] font-semibold tracking-[-.035em]">{pageTitle}</h1><p className="mt-2 text-xs text-slate-400">{currentCase?.caseNumber} · <span className="text-emerald-300">Active authorization</span> · Kathmandu partner scope</p></div><div className="flex flex-wrap justify-end gap-2">{data.demoMode && role === 'administrator' && <Button onClick={resetDemo}>Reset demo</Button>}{role !== 'reviewer' && <Button onClick={() => setModal('place')}>Analyse image place</Button>}<Button onClick={() => setModal('search')}>Add reference media</Button><Button kind="primary" onClick={() => setModal('watchlist')}>+ New watchlist</Button></div></div>
          <div className="mb-5 flex items-center gap-3 rounded-md border border-[#433642] bg-gradient-to-r from-[#a43d5124] to-[#2024304d] px-3.5 py-2.5 text-xs text-slate-300"><span className="grid h-[18px] w-[18px] place-items-center rounded bg-[#743543] font-bold text-rose-100">!</span><p className="flex-1"><b className="text-rose-200">Investigative leads, not live locations.</b> Sightings are restricted to authorized partner sources and require human review before becoming verified.</p><button onClick={() => setView('policy')} className="text-[11px] font-semibold text-[#80cfc8]">View safeguards →</button></div>
          <div className="mb-3.5 grid grid-cols-4 gap-3"><Metric label="ACTIVE WATCHLISTS" value={data.watchlists.filter((item) => item.status === 'active').length} detail="One vehicle identity under time limit" /><Metric label="REVIEW REQUIRED" value={pending.length} detail="Candidate awaiting a trained reviewer" /><Metric label="VERIFIED SIGHTINGS" value={verified.length} detail="Human-approved evidence in this case" /><Metric label="PARTNER COVERAGE" value={data.cameras.length} detail="Authorized, fixed-location sources" /></div>
          <PlaceAnalysisSummary detection={data.placeDetection} outcome={placeAnalysis} canAnalyse={role !== 'reviewer'} demoMode={data.demoMode} onAnalyse={() => { setPlaceAnalysis(null); setModal('place'); }} onSynthetic={createSyntheticPlaceLead} />
          <div className="grid grid-cols-[1.6fr_1fr] gap-3.5"><Panel><header className="flex items-start justify-between border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">SIGHTING MAP</p><h2 className="mt-1 text-base font-semibold">Case route context</h2></div><div className="flex gap-2.5 text-[9px] text-slate-400"><span><i className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-mint" />Verified</span><span><i className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-amber-400" />Under review</span></div></header><p className="border-b border-[#3a2935] bg-[#241b26] px-5 py-1.5 text-[10px] text-rose-200">Confidence-based route context only. It does not predict the vehicle’s present location.</p><MapContext sightings={data.map.sightings || []} maps={data.maps} /><footer className="flex justify-between border-t border-[#222c3b] px-5 py-2.5 text-[10px] text-slate-400"><span>{verified.length} verified sighting{verified.length === 1 ? '' : 's'} · {pending.length} candidate{pending.length === 1 ? '' : 's'} under review</span><span>{data.maps?.enabled ? 'Google Maps surface' : 'Local map-context fallback'}</span></footer></Panel>
            <Panel><header className="flex items-start justify-between border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">HUMAN REVIEW GATE</p><h2 className="mt-1 text-base font-semibold">Next candidate</h2></div><button onClick={() => setView('review')} className="text-[11px] font-semibold text-[#80cfc8]">Open queue →</button></header>{pending[0] ? <div className="flex min-h-[398px] flex-col p-5"><div className="flex justify-between"><span className="rounded-full bg-[#173b34] px-2 py-1 text-[9px] font-bold text-emerald-200">PENDING REVIEW</span><b className="text-[11px] text-amber-200">{Math.round(pending[0].confidence * 100)}% confidence</b></div><p className="mt-6 font-mono text-[25px] tracking-[.04em]">{pending[0].plateRead || 'NO PLATE READ'}</p><p className="mt-1 text-[11px] text-slate-400">{watchlistById(pending[0].watchlistId)?.vehicle?.make} {watchlistById(pending[0].watchlistId)?.vehicle?.model} · {watchlistById(pending[0].watchlistId)?.vehicle?.color}</p><div className="my-4 grid grid-cols-2 gap-3 border-y border-[#273142] py-3.5 text-[11px]"><span><small className="block text-[9px] tracking-[.08em] text-slate-500">CAPTURED</small><b>{formatTime(pending[0].capturedAt)} NPT</b></span><span><small className="block text-[9px] tracking-[.08em] text-slate-500">CAMERA</small><b>{cameraById(pending[0].cameraId)?.name}</b></span><span><small className="block text-[9px] tracking-[.08em] text-slate-500">DIRECTION</small><b>{pending[0].direction}</b></span><span><small className="block text-[9px] tracking-[.08em] text-slate-500">EVIDENCE</small><b>Encrypted reference</b></span></div><p className="text-[10px] leading-relaxed text-slate-300">A possible match is a lead only. Compare plate characters, vehicle attributes, source integrity, and context before deciding.</p><Button className="mt-auto w-full" kind="primary" onClick={() => setView('review')}>Review candidate</Button></div> : <p className="p-5 text-sm text-slate-400">No candidates currently require review.</p>}</Panel></div>
          <div className="mt-3.5 grid grid-cols-[1.07fr_.93fr] gap-3.5"><Panel><header className="flex items-start justify-between border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">ACTIVE WATCHLIST</p><h2 className="mt-1 text-base font-semibold">Target profile</h2></div><button onClick={() => setView('cases')} className="text-[11px] font-semibold text-[#80cfc8]">Manage →</button></header>{target && <div className="flex items-center gap-4 px-5 py-[18px]"><b className="rounded border border-[#5a6070] bg-[#e8eaec] px-2.5 py-2 font-mono text-[15px] text-[#1a2430]">{target.plate}</b><div className="grid flex-1 grid-cols-3 gap-5 text-[11px]"><span><small className="block text-[9px] tracking-[.1em] text-slate-500">VEHICLE</small><b>{target.vehicle.make} {target.vehicle.model}</b></span><span><small className="block text-[9px] tracking-[.1em] text-slate-500">DESCRIPTION</small><b>{target.vehicle.color} · {target.vehicle.type || '—'}</b></span><span><small className="block text-[9px] tracking-[.1em] text-slate-500">AUTO-EXPIRES</small><b>{formatTime(target.expiresAt)} NPT</b></span></div></div>}</Panel><Panel><header className="flex items-start justify-between border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">AUDIT CONTINUITY</p><h2 className="mt-1 text-base font-semibold">Recent protected events</h2></div><button onClick={exportAudit} className="text-[11px] font-semibold text-[#80cfc8]">Export log →</button></header><ol className="px-5 py-2">{data.audit.length ? data.audit.slice(-4).reverse().map((item) => <li key={item.id} className="border-b border-[#202b39] py-2.5 pl-4 text-[10px] text-slate-400 last:border-0"><b className="text-slate-200">{item.action.replaceAll('.', ' ')}</b> · {item.actor}<br /><small>{formatTime(item.at)} NPT · hash {item.hash.slice(0, 10)}…</small></li>) : <li className="py-4 text-[11px] text-slate-400">Audit records append on each protected action.</li>}</ol></Panel></div>
          <Panel className="mt-3.5"><header className="flex items-start justify-between border-b border-[#222c3b] px-5 pb-4 pt-5"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">IMAGE LOCATION LEADS</p><h2 className="mt-1 text-base font-semibold">Possible places from authorized images</h2></div><span className="rounded border border-[#3b4857] bg-[#101925] px-2 py-1 text-[9px] text-slate-300">{data.placeDetection?.localGeocoderEnabled ? 'EXIF + LOCAL OCR + GAZETTEER' : data.placeDetection?.localOcrEnabled ? 'EXIF + LOCAL OCR' : data.placeDetection?.landmarkProviderEnabled ? 'GPS + FALLBACK LANDMARK' : 'EMBEDDED GPS ONLY'}</span></header><p className="border-b border-[#3a2935] bg-[#241b26] px-5 py-2 text-[10px] text-rose-200">A place result is a confidence-based lead, not a current location. It is never verified without documented human review.</p>{placeLeads.length ? <div className="divide-y divide-[#222c3b]">{placeLeads.slice(0, 3).map((item) => <article key={item.id} className="grid grid-cols-[1.1fr_.85fr_1.25fr] items-center gap-5 px-5 py-4"><div><div className="flex items-center gap-2"><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${item.status === 'verified' ? 'bg-[#173b34] text-emerald-200' : item.status === 'rejected' ? 'bg-[#442730] text-rose-200' : 'bg-[#49361b] text-amber-200'}`}>{item.status.replaceAll('_', ' ').toUpperCase()}</span>{item.sourceKind === 'synthetic_demo' && <span className="text-[9px] font-semibold text-amber-200">SYNTHETIC</span>}</div><h3 className="mt-2 text-[12px] font-semibold">{item.label || 'No place signal'}</h3><p className="mt-1 text-[10px] text-slate-400">{item.provider} · {item.confidence == null ? 'No confidence' : `${Math.round(item.confidence * 100)}% confidence`}</p></div><div className="text-[10px] text-slate-400"><p className="text-[9px] font-bold tracking-[.1em] text-slate-500">LOCATION</p><b className="mt-1 block text-slate-200">{item.latitude == null ? 'No coordinates returned' : `${item.latitude.toFixed(4)}, ${item.longitude.toFixed(4)}`}</b><p className="mt-1">{formatTime(item.createdAt)} NPT</p></div><div>{item.status === 'pending_review' && ['reviewer', 'supervisor', 'administrator'].includes(role) ? <div><label className="text-[9px] font-semibold tracking-[.1em] text-slate-400">REVIEWER REASONING (REQUIRED)<textarea value={reasons[`place:${item.id}`] || ''} onChange={(event) => setReasons({ ...reasons, [`place:${item.id}`]: event.target.value })} className="mt-1.5 h-16 w-full resize-y rounded border border-[#324053] bg-[#0e1520] p-2 text-[10px] text-white outline-none focus:border-mint" placeholder="Compare source provenance, image context, and location signal." /></label><div className="mt-1.5 flex gap-1.5"><Button className="flex-1 px-2 py-2" onClick={() => reviewPlaceLead(item.id, 'reject')}>Reject</Button><Button className="flex-1 px-2 py-2" onClick={() => reviewPlaceLead(item.id, 'escalate')}>Escalate</Button><Button kind="primary" className="flex-1 px-2 py-2" onClick={() => reviewPlaceLead(item.id, 'approve')}>Approve</Button></div></div> : <p className="text-[10px] leading-relaxed text-slate-400">{item.reviewerReason || item.explanation}</p>}</div></article>)}</div> : <p className="px-5 py-6 text-[11px] text-slate-400">No image place leads are recorded for this case.</p>}</Panel>
        </>}

        {view === 'cases' && <div><PageHeading eyebrow="CASE MANAGEMENT" title={pageTitle} description="Every vehicle match is limited to a documented authority and an expiry." action={<Button kind="primary" onClick={() => setModal('case')}>+ Create case</Button>} /><Panel className="px-5"><table className="w-full text-left"><thead className="text-[9px] tracking-[.11em] text-slate-500"><tr>{['CASE', 'AUTHORITY', 'SCOPE', 'EXPIRY', 'STATUS'].map((label) => <th className="border-b border-[#2a3442] py-3.5" key={label}>{label}</th>)}</tr></thead><tbody>{data.cases.map((item) => <tr key={item.id} className="text-[11px] text-slate-300"><td className="border-b border-[#1d2736] py-4"><b>{item.caseNumber}</b><br /><small>{item.title}</small></td><td className="border-b border-[#1d2736] py-4">{item.authorityRef}</td><td className="border-b border-[#1d2736] py-4">{item.accessScope}</td><td className="border-b border-[#1d2736] py-4">{formatTime(item.expiresAt)} NPT</td><td className="border-b border-[#1d2736] py-4"><span className="rounded-full bg-[#173b34] px-2 py-1 text-[9px] font-bold text-emerald-200">{item.status.toUpperCase()}</span></td></tr>)}</tbody></table></Panel><div className="mt-3.5 grid grid-cols-2 gap-3.5"><Panel className="p-[22px]"><h3 className="text-sm font-semibold">Reference-media search</h3><p className="my-2 text-[11px] leading-relaxed text-slate-400">Submit only platform-supplied, rights-holder, or authorized-submitter media. The search service works against case-approved partner feeds only.</p><Button onClick={() => setModal('search')}>Create search job</Button></Panel><Panel className="p-[22px]"><h3 className="text-sm font-semibold">Automatic stop</h3><p className="mt-2 text-[11px] leading-relaxed text-slate-400">When the case or watchlist expires, the edge layer must stop matching and retain only agency-approved evidence records.</p></Panel></div></div>}

        {view === 'review' && <div><PageHeading eyebrow="REVIEW QUEUE" title={pageTitle} description="No candidate is dispatched or promoted to a verified map sighting without a trained reviewer." badge="REVIEWER ACTION REQUIRED" /> <div className="grid gap-3.5">{pending.length ? pending.map((item) => <Panel key={item.id} className="grid grid-cols-[1.1fr_1.2fr_.6fr] items-center gap-7.5 p-[22px]"><div><p className="text-[9px] font-bold tracking-[.13em] text-slate-400">POSSIBLE MATCH · {Math.round(item.confidence * 100)}% CONFIDENCE</p><p className="mt-2 font-mono text-[25px] tracking-[.04em]">{item.plateRead || 'NO PLATE'}</p><p className="mt-1 text-[11px] text-slate-400">{cameraById(item.cameraId)?.name} · {formatTime(item.capturedAt)} NPT · {item.direction}</p></div><label className="text-[9px] font-semibold tracking-[.1em] text-slate-400">REVIEWER REASONING (REQUIRED)<textarea value={reasons[item.id] || ''} onChange={(event) => setReasons({ ...reasons, [item.id]: event.target.value })} className="mt-1.5 h-[73px] w-full resize-y rounded border border-[#324053] bg-[#0e1520] p-2.5 text-[11px] text-white outline-none focus:border-mint" placeholder="Describe plate comparison, vehicle attributes, source integrity, and decision basis." /></label><div><p className="text-[9px] font-semibold tracking-[.1em] text-slate-400">DECISION</p><div className="mt-1.5 flex gap-1.5"><Button className="flex-1 px-2 py-2" onClick={() => review(item.id, 'reject')}>Reject</Button><Button className="flex-1 px-2 py-2" onClick={() => review(item.id, 'escalate')}>Escalate</Button></div><Button kind="primary" className="mt-1.5 w-full px-2 py-2" onClick={() => review(item.id, 'approve')}>Approve sighting</Button></div></Panel>) : <Panel className="border-dashed p-8 text-center text-sm text-slate-400">The reviewer queue is clear. New edge candidates remain unverified until assessed here.</Panel>}</div></div>}

        {view === 'cameras' && <div><PageHeading eyebrow="AUTHORIZED SOURCES" title={pageTitle} description="Fixed-location cameras are registered with ownership, direction, retention, and authorization before use." action={<Button onClick={() => setModal('camera')}>Register camera</Button>} /><div className="grid grid-cols-3 gap-3.5">{data.cameras.map((item) => <Panel key={item.id} className="p-5"><header className="mb-5 flex justify-between"><span className={`text-[9px] font-bold tracking-[.08em] ${item.status === 'degraded' ? 'text-amber-300' : 'text-emerald-300'}`}>● {item.status.toUpperCase()}</span><span className="text-[9px] tracking-[.1em] text-slate-500">{item.sourceType.replace('_', ' ')}</span></header><h3 className="text-[13px] font-semibold">{item.name}</h3><p className="mt-1 h-7 text-[10px] text-slate-400">{item.owner}</p><div className="grid gap-2.5 border-t border-[#263142] pt-3.5 text-[10px]">{[['LOCATION', item.location.label], ['DIRECTION', item.direction], ['RETENTION', `${item.retentionDays} days`], ['AUTHORIZATION', item.authorizationRef]].map(([label, value]) => <div className="flex justify-between gap-2" key={label}><span className="text-slate-500">{label}</span><b className="text-right font-medium text-slate-300">{value}</b></div>)}</div></Panel>)}</div></div>}

        {view === 'models' && <div>
          <PageHeading eyebrow="MODEL GOVERNANCE" title={pageTitle} description="Training labels stay case-scoped, reviewer-verified, and stored as references—not raw images. Model outputs remain leads until separately reviewed." action={<div className="flex flex-wrap gap-2">{['operator', 'supervisor', 'administrator'].includes(role) && <Button onClick={() => setModal('training-example')}>+ Add training label</Button>}{role === 'administrator' && <Button onClick={() => setModal('dataset')}>+ Dataset</Button>}{role === 'administrator' && <Button kind="primary" onClick={() => setModal('model')}>+ Register model</Button>}</div>} />
          <div className="grid grid-cols-3 gap-3.5">
            <Panel className="p-5"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">CASE DATASETS</p><strong className="mt-2 block text-[29px] tracking-[-.05em]">{String(data.datasets.length).padStart(2, '0')}</strong><p className="mt-1 text-[10px] leading-relaxed text-slate-400">Only documented `gs://` objects may become label candidates.</p></Panel>
            <Panel className="p-5"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">REGISTERED MODELS</p><strong className="mt-2 block text-[29px] tracking-[-.05em]">{String(data.models.length).padStart(2, '0')}</strong><p className="mt-1 text-[10px] leading-relaxed text-slate-400">Evaluation records and pilot approval are captured before results are accepted.</p></Panel>
            <Panel className="p-5"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">PENDING MODEL FINDINGS</p><strong className="mt-2 block text-[29px] tracking-[-.05em]">{String(pendingModelFindings.length).padStart(2, '0')}</strong><p className="mt-1 text-[10px] leading-relaxed text-slate-400">No score changes a place lead or map record on its own.</p></Panel>
          </div>
          <Panel className="mt-3.5 p-5"><header className="flex flex-wrap items-start justify-between gap-3 border-b border-[#263142] pb-4"><div><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">VERTEX AI HANDOFF</p><h2 className="mt-1 text-base font-semibold">Reviewer-verified training datasets</h2></div><span className={`rounded border px-2 py-1 text-[9px] ${data.modelGovernance?.vertexProjectConfigured ? 'border-[#2d514b] bg-[#2e64571f] text-[#9bd7c2]' : 'border-[#674c27] bg-[#372a17] text-amber-200'}`}>{data.modelGovernance?.vertexProjectConfigured ? `PROJECT READY · ${data.modelGovernance?.vertexRegion || 'REGION NOT SET'}` : 'PROJECT CONNECTION NOT CONFIGURED'}</span></header><p className="mt-3 rounded border border-[#2d4050] bg-[#0e1622] px-3 py-2 text-[10px] leading-relaxed text-slate-400">The export is a custom-training handoff manifest. It contains controlled GCS references, checksums, and approved annotations; it never exports raw media from this console. Adapt the annotation payload to the selected Vertex dataset type inside the approved cloud project.</p><div className="mt-4 grid gap-3">{data.datasets.length ? data.datasets.map((dataset) => <article key={dataset.id} className="flex flex-wrap items-center justify-between gap-4 rounded border border-[#263142] bg-[#0c121c] p-3.5"><div><div className="flex items-center gap-2"><b className="text-[12px]">{dataset.name}</b><span className="rounded-full bg-[#1b2b3b] px-2 py-1 text-[8px] font-bold tracking-[.08em] text-[#a8d8f6]">{dataset.task.replaceAll('_', ' ').toUpperCase()}</span></div><p className="mt-1 text-[10px] text-slate-400">{dataset.exampleCount} examples · {dataset.modelCount} registered models · {dataset.storageRegion}</p><p className="mt-1 text-[9px] text-slate-500">Authority: {dataset.authorizationRef}</p></div>{['supervisor', 'administrator'].includes(role) ? <Button onClick={() => exportVertexManifest(dataset)}>Export verified labels</Button> : <span className="text-[9px] text-slate-500">Supervisor export required</span>}</article>) : <p className="py-5 text-center text-[11px] text-slate-400">No training datasets are assigned to this case.</p>}</div></Panel>
          <div className="mt-3.5 grid grid-cols-2 gap-3.5"><Panel className="p-5"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">MODEL REGISTRY</p><div className="mt-4 grid gap-3">{data.models.map((model) => <article key={model.id} className="rounded border border-[#263142] bg-[#0c121c] p-3.5"><div className="flex items-center justify-between gap-3"><b className="text-[12px]">{model.name}</b><span className={`rounded-full px-2 py-1 text-[8px] font-bold tracking-[.08em] ${model.status === 'approved_for_pilot' ? 'bg-[#173b34] text-emerald-200' : 'bg-[#49361b] text-amber-200'}`}>{model.status.replaceAll('_', ' ').toUpperCase()}</span></div><p className="mt-1 text-[10px] text-slate-400">{model.provider.replaceAll('_', ' ')} · {model.task.replaceAll('_', ' ')} · {model.version}</p><p className="mt-2 text-[9px] text-slate-500">Approval: {model.approvalRef}</p></article>)}</div></Panel><Panel className="p-5"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">MODEL OUTPUT CONTRACT</p><h3 className="mt-2 text-sm font-semibold">Grounded signals, not autonomous decisions.</h3><ol className="mt-4 grid gap-3 text-[11px] leading-relaxed text-slate-400"><li><b className="mr-2 text-signal">01</b>Only approved pilot models may submit a case finding.</li><li><b className="mr-2 text-signal">02</b>Findings must name one or more bounded signals: OCR, vehicle, GPS, landmark, or map/camera context.</li><li><b className="mr-2 text-signal">03</b>The evidence score prioritises review; it cannot mark an address, vehicle, or route as verified.</li></ol></Panel></div>
          <Panel className="mt-3.5"><header className="border-b border-[#263142] px-5 py-4"><p className="text-[9px] font-bold tracking-[.12em] text-slate-500">MODEL FINDING REVIEW</p><h2 className="mt-1 text-base font-semibold">Evidence-score queue</h2></header>{modelFindings.length ? <div className="divide-y divide-[#222c3b]">{modelFindings.map((item) => <article key={item.id} className="grid grid-cols-[1.1fr_1.2fr_.6fr] gap-5 px-5 py-4"><div><div className="flex items-center gap-2"><span className={`rounded-full px-2 py-1 text-[8px] font-bold ${item.status === 'accepted_for_case' ? 'bg-[#173b34] text-emerald-200' : item.status === 'rejected' ? 'bg-[#442730] text-rose-200' : 'bg-[#49361b] text-amber-200'}`}>{item.status.replaceAll('_', ' ').toUpperCase()}</span><span className="text-[9px] text-slate-500">{item.model?.name}</span></div><h3 className="mt-2 text-[12px] font-semibold">{item.task.replaceAll('_', ' ')}</h3><p className="mt-1 text-[10px] text-slate-400">Model confidence {Math.round(item.confidence * 100)}% · evidence score {Math.round(item.evidenceScore * 100)}%</p><p className="mt-2 text-[10px] leading-relaxed text-slate-500">{item.explanation || 'No additional explanation supplied.'}</p></div><div className="text-[10px] text-slate-400">{item.evidence.map((signal, index) => <p key={`${signal.type}-${index}`} className="mb-2 rounded border border-[#263142] bg-[#0d1520] px-2.5 py-2"><b className="text-[9px] text-[#a8d8f6]">{signal.type.replaceAll('_', ' ').toUpperCase()} · {Math.round(signal.confidence * 100)}%</b><span className="mt-1 block">{signal.claim}</span></p>)}</div><div>{item.status === 'pending_review' && ['reviewer', 'supervisor', 'administrator'].includes(role) ? <div><label className="text-[9px] font-semibold tracking-[.1em] text-slate-400">REVIEWER REASONING<textarea value={reasons[`model:${item.id}`] || ''} onChange={(event) => setReasons({ ...reasons, [`model:${item.id}`]: event.target.value })} className="mt-1.5 h-16 w-full resize-y rounded border border-[#324053] bg-[#0e1520] p-2 text-[10px] text-white outline-none focus:border-mint" placeholder="Assess source integrity, signal independence, and case relevance." /></label><div className="mt-1.5 grid grid-cols-2 gap-1.5"><Button className="px-2 py-2" onClick={() => reviewModelFinding(item.id, 'reject')}>Reject</Button><Button className="px-2 py-2" onClick={() => reviewModelFinding(item.id, 'escalate')}>Escalate</Button></div><Button kind="primary" className="mt-1.5 w-full px-2 py-2" onClick={() => reviewModelFinding(item.id, 'approve')}>Accept for case</Button></div> : <p className="text-[10px] leading-relaxed text-slate-400">{item.reviewerReason || 'Awaiting an assigned reviewer.'}</p>}</div></article>)}</div> : <p className="px-5 py-7 text-center text-[11px] text-slate-400">No model findings are recorded for this case.</p>}</Panel>
        </div>}

        {view === 'policy' && <div><PageHeading eyebrow="OPERATIONAL SAFEGUARDS" title={pageTitle} description="This pilot is for active, authorized cases—never a general vehicle tracking database." badge="PILOT CONTROL SET" /><div className="grid grid-cols-3 gap-3.5">{[['01', 'Case-scoped matching', 'Edge agents submit only possible matches to active watchlists. General detections stay at the authorized partner edge.'], ['02', 'Human review before use', 'Reviewers approve, reject, or escalate every candidate. Rejected candidates never appear as verified sightings.'], ['03', 'Traceable evidence', 'Only encrypted evidence references and checksums reach the console. Accesses and decisions append to an audit chain.'], ['04', 'Authorized sources only', 'No social-media scraping, third-party stream capture, or undisclosed feeds. Every camera records an owner and authorization reference.'], ['05', 'Time-bound retention', 'Cases, watchlists, and evidence have expiry controls. Agency retention and deletion rules must be finalized before production use.'], ['06', 'Role & export controls', 'Operators create cases, reviewers decide candidates, and supervisors export audit trails. Production deployment requires MFA and an agency IdP.']].map(([number, heading, copy]) => <Panel key={number} className="min-h-[190px] p-[22px]"><span className="block text-[10px] font-bold tracking-[.1em] text-signal">{number}</span><h3 className="mt-7 text-sm font-semibold">{heading}</h3><p className="mt-2 text-[11px] leading-relaxed text-slate-400">{copy}</p></Panel>)}</div></div>}
      </div>
    </main>

    {modal === 'watchlist' && <Modal title="Create watchlist" kicker="CASE-SCOPED MATCHING" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">This record will expire with the active case and will be sent only to approved partner edge agents.</p><Input label="Plate number" name="plate" required placeholder="BA 13 PA 4421" /><div className="grid grid-cols-2 gap-3"><Input label="Make" name="make" placeholder="Suzuki" /><Input label="Model" name="model" placeholder="Swift" /></div><div className="grid grid-cols-2 gap-3"><Input label="Colour" name="color" placeholder="Pearl white" /><Input label="Expiry" name="expiresAt" type="datetime-local" defaultValue={formatDateInput(currentCase.expiresAt)} required /></div><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Create restricted watchlist</Button></footer></form></Modal>}
    {modal === 'case' && <Modal title="Create active case" kicker="DOCUMENTED AUTHORITY" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">A case remains inactive without a future expiry and authority reference.</p><Input label="Case number" name="caseNumber" required placeholder="KTM-2026-XXXX" /><Input label="Case title" name="title" required /><Input label="Authority reference" name="authorityRef" required /><Input label="Expiry" name="expiresAt" type="datetime-local" required /><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Create restricted case</Button></footer></form></Modal>}
    {modal === 'search' && <Modal title="Create search job" kicker="AUTHORIZED REFERENCE MEDIA" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Direct social or third-party stream capture is prohibited. Provide a verified evidence-vault reference only.</p><Input label="Evidence reference" name="evidenceId" required placeholder="vault://case/…" /><Input label="Evidence checksum" name="checksum" required placeholder="SHA-256 checksum" /><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Queue restricted search</Button></footer></form></Modal>}
    {modal === 'place' && <Modal title="Find a possible location from an image" kicker="CASE-SCOPED IMAGE LEAD" onClose={() => !placeSubmitting && setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Upload a local image supplied by the platform, a rights holder, or an authorized submitter. It is analysed in memory; this console retains only a checksum and reviewable lead metadata.</p><div className="mt-3 grid grid-cols-3 gap-2"><span className="rounded border border-[#2d514b] bg-[#10231f] px-2 py-2 text-[9px] text-emerald-100">01 · GPS metadata</span><span className={`rounded border px-2 py-2 text-[9px] ${data.placeDetection?.localOcrEnabled ? 'border-[#2d514b] bg-[#10231f] text-emerald-100' : 'border-[#4f4025] bg-[#211b14] text-amber-100'}`}>02 · Local OCR</span><span className={`rounded border px-2 py-2 text-[9px] ${data.placeDetection?.pilotGazetteerEnabled || data.placeDetection?.localGeocoderEnabled || data.placeDetection?.googleVisionFallbackEnabled ? 'border-[#2d514b] bg-[#10231f] text-emerald-100' : 'border-[#4f4025] bg-[#211b14] text-amber-100'}`}>03 · Address match</span></div><Input label="Authorized submitter / evidence authority" name="submitterAuthority" required placeholder="Evidence receipt or authority reference" disabled={placeSubmitting} /><PlaceDropzone file={placeFile} onFile={setPlaceFile} onError={setPlaceFileError} maxBytes={data.placeDetection?.maxImageBytes || 5 * 1024 * 1024} disabled={placeSubmitting} /><PlaceAnalysisFeedback outcome={placeAnalysis} fileError={placeFileError} geocoderReady={Boolean(data.placeDetection?.pilotGazetteerEnabled || data.placeDetection?.localGeocoderEnabled || data.placeDetection?.googleVisionFallbackEnabled)} /><p className="mt-3 rounded border border-[#3a2935] bg-[#241b26] px-3 py-2 text-[10px] leading-relaxed text-rose-200">A returned address or landmark is a confidence-based lead, never proof of where a person or vehicle is. A reviewer must assess source integrity and context before it is used.</p><footer className="mt-5 flex flex-wrap justify-end gap-2"><Button type="button" disabled={placeSubmitting} onClick={() => setModal(null)}>Cancel</Button>{data.demoMode && <Button type="button" disabled={placeSubmitting} onClick={createSyntheticPlaceLead}>Use synthetic sample</Button>}<Button kind="primary" type="submit" disabled={!placeFile || placeSubmitting}>{placeSubmitting ? 'Checking image…' : placeAnalysis?.disposition === 'no_location_signal' ? 'Try another image' : 'Analyse possible location'}</Button></footer></form></Modal>}
    {modal === 'camera' && <Modal title="Register camera" kicker="PARTNER SOURCE REGISTRY" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Production registration requires written partner authorization. This control is restricted to administrators.</p><Input label="Camera name" name="name" required /><Input label="Partner owner" name="owner" required /><div className="grid grid-cols-2 gap-3"><Input label="Latitude" name="lat" type="number" step=".0001" defaultValue="27.7100" required /><Input label="Longitude" name="lng" type="number" step=".0001" defaultValue="85.3200" required /></div><Input label="Direction" name="direction" required placeholder="Northbound" /><div className="grid grid-cols-2 gap-3"><Input label="Retention days" name="retentionDays" type="number" defaultValue="7" required /><Input label="Authorization ref" name="authorizationRef" required /></div><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Register authorized camera</Button></footer></form></Modal>}
    {modal === 'dataset' && <Modal title="Create training dataset" kicker="AUTHORIZED MODEL DATA" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Create a case-scoped label set only when the authority reference permits model training. Raw media stays in the approved evidence vault or GCS, not this console database.</p><Input label="Dataset name" name="name" required placeholder="Kathmandu vehicle attributes v1" /><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">TRAINING TASK<select name="task" required defaultValue="vehicle_detection" className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint"><option value="vehicle_detection">Vehicle detection</option><option value="vehicle_reidentification">Vehicle re-identification</option><option value="plate_ocr">Plate OCR</option><option value="place_geolocation">Place geolocation</option></select></label><Input label="Training authority reference" name="authorizationRef" required placeholder="Approval / data-sharing reference" /><Input label="Approved storage region" name="storageRegion" required defaultValue="asia-south1" /><Input label="Label schema JSON" name="labelSchema" defaultValue="{}" /><Input label="Description" name="description" placeholder="Purpose and consent scope" /><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Create dataset</Button></footer></form></Modal>}
    {modal === 'training-example' && <Modal title="Add training label" kicker="REVIEW-REQUIRED GROUND TRUTH" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Submit only a controlled `gs://` image reference and a documented label. The label is excluded from all exports until a reviewer verifies it.</p><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">DATASET<select name="datasetId" required defaultValue={data.datasets[0]?.id} className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint">{data.datasets.map((dataset) => <option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}</select></label><Input label="GCS image reference" name="storageReference" required placeholder="gs://approved-bucket/case/image.jpg" /><Input label="Source SHA-256 hash" name="sourceHash" required /><Input label="Evidence checksum" name="checksum" required /><Input label="Source filename" name="sourceFilename" placeholder="image.jpg" /><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">IMAGE MIME TYPE<select name="mimeType" defaultValue="image/jpeg" className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint"><option value="image/jpeg">image/jpeg</option><option value="image/png">image/png</option><option value="image/webp">image/webp</option></select></label><Input label="Submitter authority reference" name="submitterAuthority" required /><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">ANNOTATION JSON<textarea name="annotation" required defaultValue={'{"latitude":27.7049,"longitude":85.3075,"landmark":"Example only"}'} className="mt-1.5 h-24 w-full resize-y rounded border border-[#354155] bg-[#0b111a] p-2.5 font-mono text-[10px] text-slate-100 outline-none focus:border-mint" /></label><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Submit for label review</Button></footer></form></Modal>}
    {modal === 'model' && <Modal title="Register model profile" kicker="EVALUATION & APPROVAL" onClose={() => setModal(null)}><form onSubmit={submitModal}><p className="text-[11px] leading-relaxed text-slate-400">Register a model only after its dataset, evaluation evidence, and pilot approval are documented. A registry record does not start a cloud training job.</p><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">DATASET<select name="datasetId" required defaultValue={data.datasets[0]?.id} className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint">{data.datasets.map((dataset) => <option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}</select></label><Input label="Model name" name="name" required /><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">PROVIDER<select name="provider" defaultValue="vertex_ai" className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint"><option value="vertex_ai">Vertex AI</option><option value="google_cloud_vision">Google Cloud Vision</option><option value="custom_edge">Custom edge model</option><option value="grounded_llm">Grounded LLM</option><option value="evidence_fusion">Evidence fusion</option></select></label><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">MODEL TASK<select name="task" defaultValue="vehicle_detection" className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint"><option value="vehicle_detection">Vehicle detection</option><option value="vehicle_reidentification">Vehicle re-identification</option><option value="plate_ocr">Plate OCR</option><option value="place_geolocation">Place geolocation</option></select></label><Input label="Version" name="version" required placeholder="v1.0.0" /><label className="mt-3 block text-[10px] font-semibold tracking-[.03em] text-slate-400">STATUS<select name="status" defaultValue="evaluation" className="mt-1.5 w-full rounded border border-[#354155] bg-[#0b111a] px-2.5 py-2.5 text-xs text-slate-100 outline-none focus:border-mint"><option value="evaluation">Evaluation</option><option value="approved_for_pilot">Approved for pilot</option><option value="retired">Retired</option></select></label><Input label="Evaluation metrics JSON" name="metrics" defaultValue="{}" /><Input label="Approval reference" name="approvalRef" required /><footer className="mt-5 flex justify-end gap-2"><Button type="button" onClick={() => setModal(null)}>Cancel</Button><Button kind="primary" type="submit">Register model</Button></footer></form></Modal>}
    {notice && <div className="fixed bottom-5 right-5 z-40 rounded border border-[#3c776c] bg-[#1a2d2b] px-3.5 py-2.5 text-[11px] text-[#d8fff3] shadow-xl">{notice}</div>}
  </div>;
}

function PageHeading({ eyebrow, title, description, action, badge }) { return <div className="mb-7 flex items-end justify-between gap-8"><div><p className="text-[10px] font-bold tracking-[.13em] text-slate-400">{eyebrow}</p><h1 className="mt-2 text-[29px] font-semibold tracking-[-.035em]">{title}</h1><p className="mt-2 text-xs text-slate-400">{description}</p></div>{action || (badge && <span className="rounded border border-[#674c27] bg-[#372a17] px-2 py-1.5 text-[9px] tracking-[.1em] text-amber-200">{badge}</span>)}</div>; }
